def pandas_dtype(dtype: Any) -> Any:
    """
    Convert a dtype string or a NumPy dtype to its pandas equivalent, if the latter exists.

    Parameters
    ----------
    dtype : object

    Returns
    -------
    object
    """
    try:
        return np.dtype(dtype)
    except TypeError:
        return pandas.api.types.pandas_dtype(dtype)
